1: //go:build !windows
2: // +build !windows
3: 
4: package keyboard
5: 
6: import (
7: 	"errors"
8: 	"os"
9: 	"os/signal"
10: 	"runtime"
11: 	"strings"
12: 	"unicode/utf8"
13: 
14: 	"golang.org/x/sys/unix"
15: )
16: 
17: type (
18: 	input_event struct {
19: 		data []byte
20: 		err  error
21: 	}
22: )
23: 
24: var (
25: 	out *os.File
26: 	in  int
27: 
28: 	// term specific keys
29: 	keys []string
30: 
31: 	// termbox inner state
32: 	orig_tios unix.Termios
33: 
34: 	sigio       = make(chan os.Signal, 1)
35: 	quitEvProd  = make(chan bool)
36: 	quitConsole = make(chan bool)
37: 	inbuf       = make([]byte, 0, 128)
38: 	input_buf   = make(chan input_event)
39: )
40: 
41: func parse_escape_sequence(buf []byte) (size int, event KeyEvent) {
42: 	bufstr := string(buf)
43: 	for i, key := range keys {
44: 		if strings.HasPrefix(bufstr, key) {
45: 			event.Rune = 0
46: 			event.Key = Key(0xFFFF - i)
47: 			size = len(key)
48: 			return
49: 		}
50: 	}
51: 
52: 	// Might be an Alt combo in format of ESC+letter
53: 	if buf[0] == '\033' {
54: 		event.Key = KeyEsc
55: 		event.Rune, size = utf8.DecodeRune(buf[1:])
56: 		size = len(buf)
57: 		return
58: 	}
59: 	return 0, event
60: }
61: 
62: func extract_event(inbuf []byte) (int, KeyEvent) {
63: 	if len(inbuf) == 0 {
64: 		return 0, KeyEvent{}
65: 	}
66: 
67: 	if inbuf[0] == '\033' {
68: 		if len(inbuf) == 1 {
69: 			return 1, KeyEvent{Key: KeyEsc}
70: 		}
71: 		// possible escape sequence
72: 		if size, event := parse_escape_sequence(inbuf); size != 0 {
73: 			return size, event
74: 		} else {
75: 			// it's not a recognized escape sequence, return error
76: 			i := 1 // check for multiple sequences in the buffer
77: 			for ; i < len(inbuf) && inbuf[i] != '\033'; i++ {
78: 			}
79: 			return i, KeyEvent{Key: KeyEsc, Err: errors.New("Unrecognized escape sequence")}
80: 		}
81: 	}
82: 
83: 	// if we're here, this is not an escape sequence and not an alt sequence
84: 	// so, it's a FUNCTIONAL KEY or a UNICODE character
85: 
86: 	// first of all check if it's a functional key
87: 	if Key(inbuf[0]) <= KeySpace || Key(inbuf[0]) == KeyBackspace2 {
88: 		return 1, KeyEvent{Key: Key(inbuf[0])}
89: 	}
90: 
91: 	// the only possible option is utf8 rune
92: 	if r, n := utf8.DecodeRune(inbuf); r != utf8.RuneError {
93: 		return n, KeyEvent{Rune: r}
94: 	}
95: 
96: 	return 0, KeyEvent{}
97: }
98: 
99: // Wait for an event and return it. This is a blocking function call.
100: func inputEventsProducer() {
101: 	for {
102: 		select {
103: 		case <-quitEvProd:
104: 			return
105: 		case ev := <-input_buf:
106: 			if ev.err != nil {
107: 				select {
108: 				case <-quitEvProd:
109: 					return
110: 				case inputComm <- KeyEvent{Err: ev.err}:
111: 				}
112: 				break
113: 			}
114: 			inbuf = append(inbuf, ev.data...)
115: 			for {
116: 				size, event := extract_event(inbuf)
117: 				if size > 0 {
118: 					select {
119: 					case <-quitEvProd:
120: 						return
121: 					case inputComm <- event:
122: 					}
123: 					copy(inbuf, inbuf[size:])
124: 					inbuf = inbuf[:len(inbuf)-size]
125: 				}
126: 				if size == 0 || len(inbuf) == 0 {
127: 					break
128: 				}
129: 			}
130: 		}
131: 	}
132: }
133: 
134: func initConsole() (err error) {
